function img(url,title=''){
  const t=String(title||'').toLowerCase();
  const fallback=[
    [/imperial ascendant|ascendant/,'/covers/ascendant.jpg'],
    [/glass throne|glass/,'/covers/glass.jpg'],
    [/system named mercy|mercy/,'/covers/mercy.jpg'],
    [/neon archive|neon/,'/covers/neon.jpg'],
    [/crown of ember|ember/,'/covers/ember.jpg'],
    [/rain of swords|swords/,'/covers/swords.jpg'],
    [/silent isekai|isekai/,'/covers/isekai.jpg'],
    [/last cartographer|cartographer/,'/covers/cartographer.jpg']
  ];
  for(const [pattern,path] of fallback){if(pattern.test(t))return path}
  const value=typeof url==='string'?url.trim():'';
  return value==='/story-cover-placeholder.svg'||/^\/covers\/(ascendant|cartographer|ember|glass|isekai|mercy|neon|swords)\.jpg$/.test(value)?value:'/story-cover-placeholder.svg'
}
function ratingText(value){const rating=Number(value);return Number.isFinite(rating)&&rating>=1&&rating<=10?Math.round(rating)+'/10':'Not rated'}
function uniqueLatestStories(trendingRows,latestRows){const trendingIds=new Set((trendingRows||[]).map(row=>row?.id).filter(id=>id!==null&&id!==undefined).map(String));return (latestRows||[]).filter(row=>row?.id===null||row?.id===undefined||!trendingIds.has(String(row.id)))}
function card(n){return `<a class="card" href="/novel/${n.id}"><div class="cover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/story-cover-placeholder.svg'"></div><div class="cardBody"><div class="cardTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="meta"><span>★ ${ratingText(n.rating)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span></div></div></a>`}
function chapterRow(ch,id){return `<a class="chapter" href="/read/${id}/${ch.chapter_number}"><span class="chapterNo">${ch.chapter_number}</span><span><b>${esc(ch.title)}</b><br><span class="muted">${ch.is_locked?'Locked · '+ch.ticket_cost+' Imperial Crowns':'Free to read'}</span></span><span class="lock">${ch.is_locked?'⌑':'›'}</span></a>`}
const COMIC_FORMATS=new Set(['manga','manhwa','manhua','webtoon','comic','graphic_novel']);
function renderChapterContent(raw,kind){
 const fallback=esc(raw||'This chapter has no content yet.');
 if(!COMIC_FORMATS.has(String(kind||'').toLowerCase()))return fallback;
 let payload;try{payload=JSON.parse(String(raw||''))}catch{return fallback}
 if(payload?.type!=='imperial_comic_chapter'||payload.version!==1||!Array.isArray(payload.pages)||!payload.pages.length)return fallback;
 const pages=payload.pages.slice(0,300).map((page,i)=>{
  const src=String(page?.src||'').trim();
  const safeSrc=(src.startsWith('/')&&!src.startsWith('//')&&!src.includes('\\'))||/^https:\/\/[^\s"'<>]+$/i.test(src);
  const alt=esc(String(page?.alt||('Comic page '+(i+1))).slice(0,300));
  const caption=String(page?.caption||'').slice(0,500);
  if(!safeSrc)return '<div class="comicPageUnavailable" role="note">This page image has an invalid or unsupported address.</div>';
  return '<figure class="comicPage" data-comic-page="'+i+'"><img src="'+esc(src)+'" alt="'+alt+'" loading="'+(i===0?'eager':'lazy')+'" decoding="async"'+(i===0?' fetchpriority="high"':'')+'>'+(caption?'<figcaption>'+esc(caption)+'</figcaption>':'')+'</figure>';
 }).join('');
 return '<section class="comicReader" id="comicReader" aria-label="Comic chapter reader"><div class="comicReaderControls"><button type="button" id="comicModeToggle" class="secondary">Switch to single-page mode</button><div class="comicPageNav"><button type="button" id="comicPrev" class="readerTool" aria-label="Previous comic page" disabled>←</button><span id="comicPageStatus" aria-live="polite">Vertical scroll · '+pages.length+' pages</span><button type="button" id="comicNext" class="readerTool" aria-label="Next comic page" disabled>→</button></div></div><div class="comicPages" id="comicPages">'+pages+'</div></section>';
}
function initComicViewer(){
 const viewer=$('#comicReader');if(!viewer)return;
 const pages=$('.comicPage',viewer),toggle=$('#comicModeToggle'),prev=$('#comicPrev'),next=$('#comicNext'),status=$('#comicPageStatus');
 let single=false,current=0;
 pages.forEach(page=>{const image=$('img',page);if(image)image.addEventListener('error',()=>page.classList.add('comicPageError'),{once:true})});
 const paint=()=>{viewer.classList.toggle('is-single',single);pages.forEach((page,i)=>{page.classList.toggle('is-current',i===current);page.setAttribute('aria-hidden',String(single&&i!==current));});toggle.textContent=single?'Switch to vertical-scroll mode':'Switch to single-page mode';prev.disabled=!single||current===0;next.disabled=!single||current===pages.length-1;status.textContent=single?'Page '+(current+1)+' of '+pages.length:'Vertical scroll · '+pages.length+' pages';};
 toggle.addEventListener('click',()=>{single=!single;paint()});prev.addEventListener('click',()=>{current=Math.max(0,current-1);paint()});next.addEventListener('click',()=>{current=Math.min(pages.length-1,current+1);paint()});paint();
}
function formatKindLabel(kind){return ({original:'Original novel',fanfiction:'Fanfiction',light_novel:'Light novel',web_novel:'Web novel',manga:'Manga',manhwa:'Manhwa',manhua:'Manhua',webtoon:'Webtoon',comic:'Comic',graphic_novel:'Graphic novel',anime:'Anime listing',cartoon:'Cartoon listing',audiobook:'Audiobook listing',drama:'Drama adaptation listing',game:'Game listing'})[String(kind||'original').toLowerCase()]||'Story';}
function catalogCard(n){const genres=(n.genres||[]).slice(0,2).map(g=>`<span class="pill">${esc(typeof g==='string'?g:g.name)}</span>`).join('');const tags=(n.tags||[]).slice(0,2).map(t=>`<span class="pill purple">#${esc(typeof t==='string'?t:t.name)}</span>`).join('');const status=String(n.status||'ongoing');return `<a class="catalogCard" href="/novel/${n.id}"><div class="catalogCover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/story-cover-placeholder.svg'"><span class="statusBadge">${esc(status)}</span><span class="formatBadge">${esc(formatKindLabel(n.kind))}</span></div><div class="catalogBody"><div class="catalogTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="catalogStats"><span>★ ${ratingText(n.rating)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span><span>◉ ${Number(n.views||0).toLocaleString()}</span></div><div class="catalogTags">${genres}${tags}</div><span class="readMini">${['anime','cartoon','audiobook','drama','game'].includes(String(n.kind||'').toLowerCase())?'View Details →':'Read Story →'}</span></div></a>`}
const IMPERIAL_THEMES=['light','dark','sepia','midnight','imperial','cosmic'];
const IMPERIAL_THEME_NAMES={light:'Light',dark:'Dark',sepia:'Sepia',midnight:'Midnight',imperial:'Imperial',cosmic:'Cosmic'};
function applyImperialTheme(theme){const chosen=IMPERIAL_THEMES.includes(theme)?theme:'light';document.documentElement.dataset.theme=chosen;try{localStorage.setItem('imperial_theme',chosen)}catch(e){}const btn=document.querySelector('[data-theme-toggle]');if(btn){const next=IMPERIAL_THEMES[(IMPERIAL_THEMES.indexOf(chosen)+1)%IMPERIAL_THEMES.length];const label='Change appearance. Current theme: '+IMPERIAL_THEME_NAMES[chosen]+'. Next theme: '+IMPERIAL_THEME_NAMES[next]+'.';btn.setAttribute('aria-label',label);btn.setAttribute('title',label);btn.innerHTML=['dark','midnight','imperial','cosmic'].includes(chosen)?'☾':'☼'}return chosen}
function initImperialTheme(){let chosen='light',reduced=false,high=false,compact=false;try{chosen=localStorage.getItem('imperial_theme')||'light';reduced=localStorage.getItem('imperial_reduced_motion')==='true';high=localStorage.getItem('imperial_high_contrast')==='true';compact=localStorage.getItem('imperial_compact_cards')==='true'}catch(e){}const root=document.documentElement;root.dataset.theme=IMPERIAL_THEMES.includes(chosen)?chosen:'light';root.dataset.reducedMotion=String(reduced);root.dataset.highContrast=String(high);root.dataset.compactCards=String(compact)}
initImperialTheme();
